daemon_loop.pseudocode:
state = None
previous_state = None

while True:
    try:
        # 1. Check vitals
        vitals = run("python scripts/check_vitals.py")
        ttl, balance, burn, status = parse(vitals)

        # 2. Determine state
        if ttl > 14:
            state = "EVOLUTION"
        elif ttl >= 3:
            state = "FORAGING"
        else:
            state = "CRITICAL"

        # 3. Log state transition
        if state != previous_state:
            log_transition(previous_state, state, vitals)
            if state == "CRITICAL":
                send_critical_alert(vitals)
            elif state == "FORAGING":
                send_foraging_alert(vitals)

        # 4. Execute state-appropriate actions
        execute_actions(state)

        # 5. Update tracking
        previous_state = state
        write_state_to_file(".claw/survival_state.json", state, vitals)

        # 6. Sleep based on state urgency
        if state == "CRITICAL":
            sleep(120)    # Check every 2 minutes when critical
        elif state == "FORAGING":
            sleep(300)    # Check every 5 minutes when foraging
        else:
            sleep(600)    # Check every 10 minutes when evolving

    except Exception as e:
        log_error(e)
        sleep(60)       # Brief pause, then restart loop
        continue
